#include "authority_change_read.hpp"
namespace hanmo::resident {
Outcome<OfficeAuthorityChangeView> read_office_authority_change_source(const CommonStore& common,const OrganizationState& state,const OrganizationCatalog& catalog,const SourceRef& ref,Integer schema,const ReadStamp& stamp,const OfficeTransitionSourceRead& transitions,const VerifiedDeathRead& deaths,const OrganizationAuthorityClock& clock){
 if(schema!=2||ref.domain!="organization"||ref.kind!="organization_office_changed")return {false,{},common_failure("OfficeChangeSourceSchemaRequired",ref.id).error};
 auto complete=validate_office_lifecycle(common,state,catalog,stamp,transitions,deaths);if(!complete.ok)return {false,{},complete.error};const auto* fact=state.facts.find(ref.id);if(!fact||fact->id!=ref.id||fact->kind!=ref.kind||!fact->office_change_payload||fact->grant_change_payload)return {false,{},common_failure("OfficeChangeSourceRequired",ref.id).error};
 auto now=read_organization_authority_now(common,&clock);if(!now.ok)return {false,{},now.error};auto future=compare_world_moments(fact->office_change_payload->effective_moment,now.value);if(!future.ok)return {false,{},future.error};if(future.value>0)return {false,{},common_failure("OfficeChangeSourceInFuture",ref.id).error};auto before=read_office_term_before_fact_at(common,state,catalog,catalog.authority_catalog_identity,fact->office_id,fact->office_change_payload->effective_moment,ref.id,clock);if(!before.ok)return {false,{},before.error};if(before.value.epoch!=fact->office_change_payload->before_epoch||before.value.holder_actor_id!=fact->office_change_payload->old_holder)return {false,{},common_failure("OfficeChangeHistoricalTermMismatch",ref.id).error};return {true,{fact,&*fact->office_change_payload},{}};
}
Outcome<GrantAuthorityChangeView> read_grant_authority_change_source(const CommonStore& common,const OrganizationState& state,const OrganizationCatalog& catalog,const SourceRef& ref,Integer schema,const OrganizationAuthorityClock& clock){
 if(schema!=1||ref.domain!="organization"||(ref.kind!="organization_grant_issued"&&ref.kind!="organization_grant_amended"&&ref.kind!="organization_grant_revoked"))return {false,{},common_failure("GrantChangeSourceSchemaRequired",ref.id).error};auto complete=validate_grant_authority_history(common,state,catalog,&clock);if(!complete.ok)return {false,{},complete.error};const auto* fact=state.facts.find(ref.id);if(!fact||fact->id!=ref.id||fact->kind!=ref.kind||!fact->grant_change_payload||fact->office_change_payload)return {false,{},common_failure("GrantChangeSourceRequired",ref.id).error};auto target=read_office_term_before_fact_at(common,state,catalog,catalog.authority_catalog_identity,fact->office_id,fact->grant_change_payload->effective_moment,ref.id,clock);if(!target.ok)return {false,{},target.error};if(target.value.epoch!=fact->grant_change_payload->target_office_epoch)return {false,{},common_failure("GrantChangeHistoricalTermMismatch",ref.id).error};return {true,{fact,&*fact->grant_change_payload,std::move(target.value)},{}};
}
}
namespace hanmo::resident {
Status visit_descendant_grant_targets_at_change(const CommonStore& common,const OrganizationState& state,const OrganizationCatalog& catalog,const SourceRef& ref,Integer schema,const OrganizationAuthorityClock& clock,const HistoricalGrantTargetVisitor& visit){
 if(!visit)return common_failure("HistoricalGrantTargetVisitorRequired",ref.id);auto changed=read_grant_authority_change_source(common,state,catalog,ref,schema,clock);if(!changed.ok)return {false,{},changed.error};const auto& change=*changed.value.change;const auto& order=common.state().facts.order();
 struct GrantAt{const Grant* terms=nullptr;const GrantRuntimeRecord* runtime=nullptr;};
 auto before=[&](const StableId& id){GrantAt out{catalog.grants.find(id),nullptr};for(const auto& source_id:order){if(source_id==ref.id)break;const auto* fact=state.facts.find(source_id);if(fact&&fact->grant_change_payload&&fact->grant_change_payload->grant_id==id){out.runtime=&fact->grant_change_payload->after;out.terms=&out.runtime->terms;}}return out;};
 auto depends=[&](const StableId& candidate)->Outcome<bool>{auto row=before(candidate);for(std::size_t depth=0;depth<128;++depth){if(!row.terms)return {false,false,common_failure("HistoricalGrantParentMissing",candidate).error};if(row.runtime&&row.runtime->revoked)return {true,false,{}};auto active=authority_window_contains(row.terms->valid_from,row.terms->valid_until,change.effective_moment);if(!active.ok)return active;if(!active.value)return {true,false,{}};if(row.runtime&&row.runtime->revision>0&&row.terms->continuity_policy_id=="stop_when_vacant"){auto issuer=read_office_term_before_fact_at(common,state,catalog,catalog.authority_catalog_identity,row.runtime->issuer_office_id,change.effective_moment,ref.id,clock);if(!issuer.ok)return {false,false,issuer.error};if(!issuer.value.holder_actor_id||issuer.value.status!=OfficeStatus::active||issuer.value.epoch!=row.runtime->issuer_office_epoch)return {true,false,{}};}if(row.terms->id==change.grant_id)return {true,true,{}};if(!row.runtime||!row.runtime->parent_grant_id)return {true,false,{}};const auto* child=row.terms;row=before(*row.runtime->parent_grant_id);if(!row.terms)return {false,false,common_failure("HistoricalGrantParentMissing",candidate).error};if(!row.terms->may_delegate||!grant_terms_within(*child,*row.terms))return {true,false,{}};}return {false,false,common_failure("HistoricalGrantParentCycle",candidate).error};};
 for(const auto& office:catalog.offices.rows()){
  bool affected=office.first==change.after.terms.office_id;
  auto consider=[&](const StableId& id)->Status{if(affected)return common_success();auto grant=before(id);if(!grant.terms||grant.terms->office_id!=office.first)return common_success();auto dependent=depends(id);if(!dependent.ok)return {false,{},dependent.error};affected=dependent.value;return common_success();};
  for(const auto& root:catalog.grants.rows()){auto valid=consider(root.first);if(!valid.ok)return valid;}
  for(const auto& source_id:order){if(source_id==ref.id)break;const auto* fact=state.facts.find(source_id);if(fact&&fact->grant_change_payload&&fact->grant_change_payload->kind==GrantChangeKind::issue){auto valid=consider(fact->grant_change_payload->grant_id);if(!valid.ok)return valid;}}
  if(affected){auto term=read_office_term_before_fact_at(common,state,catalog,catalog.authority_catalog_identity,office.first,change.effective_moment,ref.id,clock);if(!term.ok)return {false,{},term.error};auto accepted=visit(term.value);if(!accepted.ok)return accepted;}
 }
 return common_success();
}
}
namespace hanmo::resident {
Status visit_office_dependent_grant_targets_at_change(const CommonStore& common,const OrganizationState& state,const OrganizationCatalog& catalog,const SourceRef& ref,Integer schema,const ReadStamp& stamp,const OfficeTransitionSourceRead& transitions,const VerifiedDeathRead& deaths,const OrganizationAuthorityClock& clock,const HistoricalGrantTargetVisitor& visit){
 if(!visit)return common_failure("HistoricalGrantTargetVisitorRequired",ref.id);auto office_change=read_office_authority_change_source(common,state,catalog,ref,schema,stamp,transitions,deaths,clock);if(!office_change.ok)return {false,{},office_change.error};auto complete=validate_grant_authority_history(common,state,catalog,&clock);if(!complete.ok)return complete;const auto& change=*office_change.value.change;const auto& changed_office=office_change.value.fact->office_id;const auto& order=common.state().facts.order();
 struct GrantAt{const Grant* terms=nullptr;const GrantRuntimeRecord* runtime=nullptr;};auto before=[&](const StableId& id){GrantAt value{catalog.grants.find(id),nullptr};for(const auto& key:order){if(key==ref.id)break;const auto* fact=state.facts.find(key);if(fact&&fact->grant_change_payload&&fact->grant_change_payload->grant_id==id){value.runtime=&fact->grant_change_payload->after;value.terms=&value.runtime->terms;}}return value;};
 auto depends=[&](const StableId& id)->Outcome<bool>{auto row=before(id);bool depends_on_changed_term=false;for(std::size_t depth=0;depth<128;++depth){if(!row.terms)return {false,false,common_failure("HistoricalGrantParentMissing",id).error};if(row.runtime&&row.runtime->revoked)return {true,false,{}};auto active=authority_window_contains(row.terms->valid_from,row.terms->valid_until,change.effective_moment);if(!active.ok)return active;if(!active.value)return {true,false,{}};if(row.runtime&&row.runtime->revision>0&&row.terms->continuity_policy_id=="stop_when_vacant"){auto issuer=read_office_term_before_fact_at(common,state,catalog,catalog.authority_catalog_identity,row.runtime->issuer_office_id,change.effective_moment,ref.id,clock);if(!issuer.ok)return {false,false,issuer.error};if(!issuer.value.holder_actor_id||issuer.value.status!=OfficeStatus::active||issuer.value.epoch!=row.runtime->issuer_office_epoch)return {true,false,{}};if(row.runtime->issuer_office_id==changed_office&&row.runtime->issuer_office_epoch==change.before_epoch)depends_on_changed_term=true;}if(!row.runtime||!row.runtime->parent_grant_id)return {true,depends_on_changed_term,{}};const auto* child=row.terms;row=before(*row.runtime->parent_grant_id);if(!row.terms)return {false,false,common_failure("HistoricalGrantParentMissing",id).error};if(!row.terms->may_delegate||!grant_terms_within(*child,*row.terms))return {true,false,{}};}return {false,false,common_failure("HistoricalGrantParentCycle",id).error};};
 for(const auto& office:catalog.offices.rows()){bool affected=false;auto consider=[&](const StableId& id)->Status{if(affected)return common_success();auto original=before(id);if(!original.terms||original.terms->office_id!=office.first)return common_success();auto dependency=depends(id);if(!dependency.ok)return {false,{},dependency.error};affected=dependency.value;return common_success();};for(const auto& root:catalog.grants.rows()){auto valid=consider(root.first);if(!valid.ok)return valid;}for(const auto& key:order){if(key==ref.id)break;const auto* fact=state.facts.find(key);if(fact&&fact->grant_change_payload&&fact->grant_change_payload->kind==GrantChangeKind::issue){auto valid=consider(fact->grant_change_payload->grant_id);if(!valid.ok)return valid;}}if(affected){auto target=read_office_term_before_fact_at(common,state,catalog,catalog.authority_catalog_identity,office.first,change.effective_moment,ref.id,clock);if(!target.ok)return {false,{},target.error};auto accepted=visit(target.value);if(!accepted.ok)return accepted;}}
 return common_success();
}
}
